import { BaseTeamInfo, BaseMapInfo } from "./types"
import { ChatTags, PlayerId, PNull, Pos, RecursiveReadonly } from "@bloxd"
import { SessionBasedGame } from "./SessionBasedGame"
import { style, getLowHigh } from "./helpers"

/** Opacity a spectator renders at. Only other spectators can see them, and themselves in third person. */
export const SPECTATOR_OPACITY = 0.5

export class SessionBasedPlayer<TeamInfo extends BaseTeamInfo, MapInfo extends BaseMapInfo<TeamInfo>> {
	isSpectating = true
	team: PNull<TeamInfo> = null
	requestedTeam: PNull<TeamInfo> = null
	qTextId: PNull<string> = null

	constructor(
		readonly playerId: PlayerId,
		readonly game: SessionBasedGame<TeamInfo, MapInfo, SessionBasedPlayer<TeamInfo, MapInfo>>,
	) {
		api.setPlayerGamemode(this.playerId, "survival")
		this.startSpectating()
		this.spawn()
	}

	private spawn() {
		const spawnPosition = this.onRespawnRequest()
		if (spawnPosition) {
			api.setPosition(this.playerId, spawnPosition)
		}
	}

	/**
	 * Sets the player as playing the game, setting their health, shields, and other settings.
	 * Automatically called at the start of a game for players assigned to a team.
	 */
	startPlaying() {
		this.isSpectating = false
		const maxHealth = api.getClientOption(this.playerId, "maxHealth")
		api.setHealth(this.playerId, maxHealth)
		if (api.getHealth(this.playerId) !== null) {
			api.setShieldAmount(this.playerId, api.getClientOption(this.playerId, "initialShield"))
		}
		api.setClientOptions(this.playerId, {
			initialHealth: maxHealth,
			creative: false,
			canAltAction: true,
			canChange: false,
			useFullInventory: true,
			cantBreakError: "",
			cantBuildError: [{ str: { translationKey: "general:cantBuildHere" } }],
			canPickUpItems: true,
			autoRespawn: true,
			secsToRespawn: 5,
			respawnButtonText: "sessionBasedGame:spectate",
			usePlayAgainButton: true,
		})
		this.updateOtherEntitySettings(false)
		api.setCanChangeBlockRect(this.playerId, ...this.game.gameOptions.playAreaRect)

		if (this.team) {
			api.setTargetedPlayerSettingForEveryone(this.playerId, "killfeedColour", this.team.colour, true)
			api.setTargetedPlayerSettingForEveryone(this.playerId, "colorInLobbyLeaderboard", this.team.colour, true)
		}

		this.spawn()
	}

	/**
	 * Sets the player as spectating the game, resetting their health, shields, and other settings.
	 * Automatically called at the start of a game for players not assigned to a team.
	 * Call this function to turn a player into a spectator (for example, once they die).
	 */
	startSpectating() {
		this.isSpectating = true
		this.team = null
		const isBeforeGame = this.game.gamePhase === "beforeGame"
		api.setClientOptions(this.playerId, {
			creative: !isBeforeGame,
			useFullInventory: false,
			canAltAction: isBeforeGame,
			canChange: false,
			cantBreakError: [
				{ str: { translationKey: "sessionBasedGame:cantChangeBlocksWhileSpectating" }, style: { colour: this.game.messageColours.error } },
			],
			cantBuildError: [
				{ str: { translationKey: "sessionBasedGame:cantChangeBlocksWhileSpectating" }, style: { colour: this.game.messageColours.error } },
			],
			canPickUpItems: true,
			autoRespawn: false,
			secsToRespawn: 3,
			respawnButtonText: isBeforeGame ? "general:respawn" : "sessionBasedGame:spectate",
			usePlayAgainButton: true,
		})
		api.setEveryoneSettingForPlayer(this.playerId, "canSee", true)
		this.updateOtherEntitySettings(true)
		api.resetCanChangeBlockRect(this.playerId, ...this.game.gameOptions.playAreaRect)

		for (const effect of api.getEffects(this.playerId)) {
			api.removeEffect(this.playerId, effect)
		}
		api.clearInventory(this.playerId)

		this.game.checkWin()
	}

	private updateOtherEntitySettings(isSpectating: boolean) {
		// pass in isSpectating in case games set it after calling startPlaying()/startSpectating()
		// Lobby players all carry isSpectating, so fading there would grey out the whole lobby
		const fadeSpectators = this.game.spectatorsAreFaded()
		for (const player of this.game.getPlayers()) {
			const canAttack = !isSpectating && !player.isSpectating && (this.playerId === player.playerId || this.team !== player.team)
			api.setOtherEntitySetting(this.playerId, player.playerId, "canAttack", canAttack)
			api.setOtherEntitySetting(player.playerId, this.playerId, "canAttack", canAttack)

			api.setOtherEntitySetting(this.playerId, player.playerId, "canSee", isSpectating || !player.isSpectating)
			api.setOtherEntitySetting(player.playerId, this.playerId, "canSee", player.isSpectating || !isSpectating)

			// Our own fade, and the only place it gets cleared again. Also covers the self pair.
			api.setOtherEntitySetting(player.playerId, this.playerId, "opacity", fadeSpectators && isSpectating ? SPECTATOR_OPACITY : 1)
			// Others are only ever faded in, never cleared, so an opacity a game set for its own
			// effect survives until that player's own startPlaying clears it.
			if (player.playerId !== this.playerId && fadeSpectators && player.isSpectating) {
				api.setOtherEntitySetting(this.playerId, player.playerId, "opacity", SPECTATOR_OPACITY)
			}
		}
	}

	onMessage(): ChatTags {
		if (this.game.gamePhase === "beforeGame") {
			return undefined
		}
		const team = this.team
		if (!team) {
			return [
				style("[", this.game.messageColours.info),
				style({ translationKey: "sessionBasedGame:spectator" }, this.game.messageColours.info),
				style("]", this.game.messageColours.info),
			]
		}

		return [style("[", team.colour), style(team.name, team.colour), style("]", team.colour)]
	}

	onRespawnRequest(): Pos | undefined {
		let spawnArea: RecursiveReadonly<{ spawn: Pos; spawnFacing: Pos }> | undefined
		if (this.team && this.game.map?.teams[this.team.name]) {
			spawnArea = this.game.map.teams[this.team.name]
		} else if (this.game.gameOptions.lobby) {
			spawnArea = this.game.gameOptions.lobby
		} else {
			return undefined
		}

		const { spawn, spawnFacing } = spawnArea
		const { low: playAreaLow } = getLowHigh(this.game.gameOptions.playAreaRect)
		const playAreaSpawn: Pos = [playAreaLow[0] + spawn[0] + 0.5, playAreaLow[1] + spawn[1] + 0.5, playAreaLow[2] + spawn[2] + 0.5]
		api.setVelocity(this.playerId, 0, 0, 0)
		api.setCameraDirection(this.playerId, spawnFacing as Pos)
		return playAreaSpawn
	}

	/**
	 * Gets the position of the player relative to the play area.
	 * @returns The position of the player relative to the play area.
	 */
	getPositionInPlayArea(): Pos {
		const { low: playAreaLow } = getLowHigh(this.game.gameOptions.playAreaRect)
		const position = api.getPosition(this.playerId)
		return [position[0] - playAreaLow[0], position[1] - playAreaLow[1], position[2] - playAreaLow[2]]
	}
}
